:root {
  --cream: #f5efe0;
  --brown-dark: #3b2410;
  --brown-mid: #7a4e2d;
  --brown-light: #c4915a;
  --gold: #c9a84c;
  --gold-light: #e8d08a;
  --rust: #8b3a1e;
  --green-muted: #4a6741;
  --border-rule: #b89660;
  --text-muted: #9a7a55;
  --bg-card: #faf3e4;
  --bg-header: #3b2410;
  --skill-track: #e0d4bc;
}

.cert-card {
  width: 480px;
  background-color: var(--bg-card);
  border: 2px solid var(--border-rule);
  border-radius: 4px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.cert-header {
  background-color: var(--bg-header);
  padding: 12px 16px;
  display: flex;
  align-items: center;
  gap: 12px;
  border-bottom: 3px solid var(--gold);
}

.guild-emblem {
  position: relative;
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.emblem-ring {
  position: absolute;
  line-height: 1;
}

.emblem-ring.outer {
  font-size: 40px;
  opacity: 0.25;
}

.emblem-ring.inner {
  font-size: 22px;
}

.cert-title-block {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.guild-name {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--gold-light);
  margin: 0;
}

.cert-title {
  font-size: 18px;
  font-weight: 800;
  color: var(--cream);
  margin: 0;
  line-height: 1.1;
}

.cert-subtitle {
  font-size: 10px;
  color: var(--text-muted);
  margin: 0;
  letter-spacing: 0.5px;
}

.cert-level {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border: 2px solid var(--gold);
  border-radius: 4px;
  padding: 4px 10px;
  flex-shrink: 0;
}

.level-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--gold-light);
}

.level-value {
  font-size: 20px;
  font-weight: 800;
  color: var(--gold);
  line-height: 1.1;
}

.cert-body {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  padding: 14px 16px;
  border-bottom: 1px solid var(--border-rule);
}

.apprentice-info {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 4px;
  padding-right: 12px;
  border-right: 1px solid var(--border-rule);
}

.info-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--text-muted);
  margin: 0;
}

.apprentice-name {
  font-size: 20px;
  font-weight: 800;
  color: var(--brown-dark);
  margin: 0;
  line-height: 1.1;
}

.apprentice-id {
  font-size: 11px;
  color: var(--brown-mid);
  margin: 0;
  font-weight: 600;
  letter-spacing: 1px;
}

.skills-grid {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.skill-item {
  display: grid;
  grid-template-columns: 18px 72px 1fr;
  align-items: center;
  gap: 6px;
}

.skill-icon {
  font-size: 12px;
  line-height: 1;
}

.skill-name {
  font-size: 11px;
  font-weight: 600;
  color: var(--brown-dark);
}

.skill-bar {
  height: 6px;
  background-color: var(--skill-track);
  border-radius: 3px;
  overflow: hidden;
}

.skill-fill {
  display: block;
  height: 100%;
  width: var(--fill);
  background-color: var(--brown-light);
  border-radius: 3px;
}

.cert-footer {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 16px;
  background-color: var(--cream);
}

.footer-stamp {
  width: 46px;
  height: 46px;
  border: 2.5px solid var(--green-muted);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.stamp-text {
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: var(--green-muted);
  text-align: center;
}

.footer-meta {
  flex: 1;
  display: flex;
  gap: 14px;
}

.meta-item {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.meta-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: var(--text-muted);
}

.meta-value {
  font-size: 12px;
  font-weight: 700;
  color: var(--brown-dark);
}

.footer-sig {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  flex-shrink: 0;
}

.sig-line {
  width: 72px;
  height: 1px;
  background-color: var(--brown-mid);
}

.sig-label {
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: var(--text-muted);
}
